/**
 * C# AST code generator: reads _scripts/ast.json (byte-for-byte upstream copy, parsed
 * through the byte-for-byte _scripts/schema.ts) and produces the seven generated files
 * of src/Ts.Compiler/Ast/ (plan/04-codegen.md §2, review verdict R2):
 *
 *   - Nodes.g.cs        brand interfaces, mixin interfaces, Node-lineage abstract bases,
 *                       node class declarations (inheritance, fields, mixin flattening)
 *   - NodeCasts.g.cs    Node.As*() casts; Ts.Ast.NodeTests Is*() guards + kind alias guards
 *   - NodeFactory.g.cs  NodeFactory fields + New*()/Update*() factories
 *   - Visitors.g.cs     ForEachChild/VisitEachChild/Clone overrides + generated computeSubtreeFacts
 *   - Accessors.g.cs    mixin virtual-accessor overrides, Name() accessors, CompositeBase
 *                       cached workers, TypeSyntaxBase re-anchoring (plan/02 §3.4)
 *   - SyntaxKind.g.cs   the SyntaxKind enum (elements + Count + markers)
 *   - GlobalUsings.g.cs the five alias families as global usings (plan/02 §13)
 *
 * Ported from tsgo _scripts/generate-go-ast.ts (1,028 lines); the emission side is new,
 * implementing the three C# generation rules of plan/02-ast-design.md §3:
 *   1. base class = the most-derived Node-lineage base in extends (4 diamond nodes);
 *   2. mixin flattening = transitive closure, fields deduped by name (shallowest wins);
 *   3. field-less brand bases become pure marker interfaces.
 * Plus the promotion-explicitation step of plan/02 §3.4 (subtree-facts provider election).
 *
 * Usage: npm run gen:ast   (node --experimental-strip-types generate-csharp-ast.ts)
 */

import * as path from "node:path";
import type {
    MemberInfo,
    NodeType,
    Type,
} from "./_scripts/schema.ts";
import {
    api,
    kindGuardName,
} from "./_scripts/schema.ts";
import {
    autoGeneratedHeader,
    CodeWriter,
    csIdentifier,
    expectedCount,
    ROOT,
    verifyUpstreamSha256,
    writeIfChanged,
} from "./csharp-emit.ts";

// ────────────────────────────────────────────────────────────────────────────
// Input pinning (UPSTREAM.lock is the single source of truth for asset bytes)
// ────────────────────────────────────────────────────────────────────────────

await verifyUpstreamSha256("ast.json", path.join(import.meta.dirname, "_scripts/ast.json"));
await verifyUpstreamSha256("schema.ts", path.join(import.meta.dirname, "_scripts/schema.ts"));

const OUT_DIR = path.join(ROOT, "src", "Ts.Compiler", "Ast");
const HEADER = autoGeneratedHeader("generate-csharp-ast.ts", ["tools/generator/_scripts/ast.json"]);

// ────────────────────────────────────────────────────────────────────────────
// Base classification (plan/02 §2): Node lineage / data mixin / brand
// ────────────────────────────────────────────────────────────────────────────

const bases = api.bases();
const baseKeys = new Set(bases.map(b => b.key));

const closureCache = new Map<string, Set<string>>();
/** Transitive extends closure over base keys (the key itself excluded). */
function extendsClosure(key: string): Set<string> {
    let cached = closureCache.get(key);
    if (cached) return cached;
    cached = new Set<string>();
    closureCache.set(key, cached);
    const base = api.getBase(key);
    for (const ext of base?.extendsKeys ?? []) {
        if (!cached.has(ext)) {
            cached.add(ext);
            for (const deeper of extendsClosure(ext)) cached.add(deeper);
        }
    }
    return cached;
}

function isNodeLineage(key: string): boolean {
    return key === "NodeBase" || extendsClosure(key).has("NodeBase");
}

function baseHasFieldsDeep(key: string): boolean {
    const base = api.getBase(key)!;
    if (base.fields.some(f => !f.noGo)) return true;
    return base.extendsKeys.some(baseHasFieldsDeep);
}

const nodeLineageBases: string[] = [];
const mixinBases: string[] = [];
const brandBases: string[] = [];
for (const base of bases) {
    if (isNodeLineage(base.key)) nodeLineageBases.push(base.key);
    else if (baseHasFieldsDeep(base.key)) mixinBases.push(base.key);
    else brandBases.push(base.key);
}
if (nodeLineageBases.length !== 18 || mixinBases.length !== 13 || brandBases.length !== 4) {
    throw new Error(`base classification drifted: ${nodeLineageBases.length} Node-lineage / ${mixinBases.length} mixin / ${brandBases.length} brand (expected 18/13/4; plan/02 §2)`);
}

// ────────────────────────────────────────────────────────────────────────────
// Rule 1: base class selection = most-derived Node-lineage base (plan/02 §3.1)
// ────────────────────────────────────────────────────────────────────────────

/** Returns the C# base class key ("NodeBase" ⇒ hand-written Node). */
function selectBaseClass(name: string, extendsKeys: string[]): string {
    const lineage = extendsKeys.filter(isNodeLineage);
    if (lineage.length === 0) {
        throw new Error(`${name}: extends has no Node-lineage base — every node must reach NodeBase`);
    }
    if (lineage.length === 1) return lineage[0];
    const maximal = lineage.filter(m => lineage.every(o => o === m || extendsClosure(m).has(o)));
    if (maximal.length !== 1) {
        throw new Error(`${name}: extends [${lineage.join(", ")}] has no unique most-derived Node-lineage base — upstream schema grew a true diamond; manual decision required (plan/02 §3.1 step 5)`);
    }
    return maximal[0];
}

function csBaseClassName(key: string): string {
    return key === "NodeBase" ? "Node" : key;
}

// ────────────────────────────────────────────────────────────────────────────
// Rule 2: mixin flattening (plan/02 §3.2) — closure BFS, first-seen wins
// ────────────────────────────────────────────────────────────────────────────

/**
 * Mixins/brands introduced by this class itself (not already introduced by its
 * selected base class), in BFS-over-extends order (shallowest first — this order
 * also drives the by-name field dedup, mirroring Go's promotion-depth rule).
 */
function newMixins(extendsKeys: string[], baseClassKey: string | null): string[] {
    const result: string[] = [];
    const seen = new Set<string>();
    const queue = [...extendsKeys];
    while (queue.length > 0) {
        const key = queue.shift()!;
        if (seen.has(key)) continue;
        seen.add(key);
        if (baseKeys.has(key) && !isNodeLineage(key)) result.push(key);
        queue.push(...(api.getBase(key)?.extendsKeys ?? []));
    }
    if (baseClassKey === null) return result;
    const inherited = new Set<string>([baseClassKey, ...extendsClosure(baseClassKey)]);
    return result.filter(key => !inherited.has(key));
}

// ────────────────────────────────────────────────────────────────────────────
// C# type formatting (mirror of schema.ts formatGoReference; plan/04 §2.2 #4)
// ────────────────────────────────────────────────────────────────────────────

const primitiveTypeMap: Record<string, string> = {
    string: "string",
    bool: "bool",
    int: "int",
    any: "object", // SyntheticExpression.Type — Go `any` (checker Type; refined in phase 4)
    NodeFlags: "NodeFlags",
    TokenFlags: "TokenFlags",
    ModifierFlags: "ModifierFlags",
};

/** goOnly members carry a raw Go type; map or reject (plan/04 §2.2 #4). */
const rawTypeMap: Record<string, string> = {
    "*FlowNode": "FlowNode?",
    "*Symbol": "Symbol?",
    "SymbolTable": "SymbolTable?",
    "*Node": "Node?",
};

/** The C# reference form of a schema type, without nullability. */
function csRefType(type: Type): string {
    switch (type.kind) {
        case "primitive": {
            const mapped = primitiveTypeMap[type.name];
            if (!mapped) throw new Error(`no C# mapping for primitive type ${type.name}`);
            return mapped;
        }
        case "kind":
            return "SyntaxKind";
        case "node":
            return api.hasNode(type.name) ? `${type.name}Node` : type.name === "Node" ? "Node" : type.name;
        case "alias":
            return type.name;
        case "typeParameter":
            return csRefType(type.constraint);
        case "union": {
            // Mirrors UnionType.formatGoReference (schema.ts:466-492).
            const concreteNodes = new Set<string>();
            let allConcreteNodes = true;
            for (const t of type.types) {
                const nodeName = t.kind === "node" || t.kind === "alias" || t.kind === "typeParameter" ? t.concreteNodeName() : undefined;
                if (!nodeName) {
                    allConcreteNodes = false;
                    break;
                }
                concreteNodes.add(nodeName);
            }
            if (allConcreteNodes && concreteNodes.size === 1) return `${[...concreteNodes][0]}Node`;
            if (type.types.some(t => t.baseKind() === "node" || t.baseKind() === "list")) return "Node";
            if (type.types.every(t => t.baseKind() === "kind")) return "SyntaxKind";
            const references = [...new Set(type.types.map(csRefType))];
            if (references.length === 1) return references[0];
            throw new Error(`cannot resolve C# reference form for union ${references.join(" | ")}`);
        }
        case "list": {
            if (type.listKind === "raw") {
                return type.elementType.baseKind() === "node" ? "Node[]" : `${csRefType(type.elementType)}[]`;
            }
            if (type.listKind === "ModifierList") return "ModifierList";
            return api.listAliasName(type.elementType) || "NodeList";
        }
    }
}

/** Value-typed C# forms never take `?`. */
function isCsValueType(type: Type): boolean {
    if (type.baseKind() === "kind") return true;
    if (type.kind === "primitive") return type.name === "bool" || type.name === "int" || type.name === "NodeFlags" || type.name === "TokenFlags" || type.name === "ModifierFlags";
    if (type.kind === "typeParameter") return isCsValueType(type.constraint);
    return false;
}

/**
 * Member type with nullability. Every Go pointer/slice/interface mirrors to a
 * nullable reference type; `m.optional` only affects the `// Optional` comment
 * (plan/04 §2.2 cross-cutting rule — the generator does no non-null inference).
 * Go `string` is a value ⇒ non-nullable string (fields get a `= ""` initializer).
 */
function csMemberType(m: MemberInfo): string {
    if (m.goOnly) {
        const raw = m.rawType;
        const mapped = typeof raw === "string" ? rawTypeMap[raw] : undefined;
        if (!mapped) throw new Error(`no C# mapping for goOnly rawType ${JSON.stringify(m.rawType)} (member ${m.name})`);
        return mapped;
    }
    const type = m.type;
    const ref = csRefType(type);
    if (isCsValueType(type) || ref === "string") return ref;
    if (ref === "object") return "object?";
    return `${ref}?`;
}

/**
 * Go-unexported check: schema marks some fields `private`, but Go privacy is really
 * the lowercase first letter (e.g. CompositeBase.facts carries no flag). Both count.
 */
function isGoPrivate(m: MemberInfo): boolean {
    const c = m.name.charAt(0);
    return m.private || (c === c.toLowerCase() && c !== c.toUpperCase());
}

/** Go constant reference (e.g. "TokenFlagsStringLiteralFlags") → C# enum member. */
function mapGoConstant(goName: string): string {
    for (const enumName of ["ModifierFlags", "NodeFlags", "TokenFlags", "SubtreeFacts"]) {
        if (goName.startsWith(enumName) && goName.length > enumName.length) {
            return `${enumName}.${goName.slice(enumName.length)}`;
        }
    }
    throw new Error(`cannot map Go constant ${goName} to a C# enum member`);
}

// ────────────────────────────────────────────────────────────────────────────
// Members participating in factory/visitor/clone (mirror generate-go-ast.ts:38-56)
// ────────────────────────────────────────────────────────────────────────────

function schemaMembers(node: NodeType): MemberInfo[] {
    return node.members.filter(m => !m.noFactory);
}

function isTextContentType(type: Type): boolean {
    if (type.kind === "primitive") return type.name === "string";
    if (type.kind === "list" && type.listKind === "raw") {
        return type.elementType.kind === "primitive" && type.elementType.name === "string";
    }
    return false;
}

function hasTextContent(node: NodeType): boolean {
    if (node.members.length === 0) return false;
    return schemaMembers(node).some(m => isTextContentType(m.type));
}

function isNodeFlagsMember(m: MemberInfo): boolean {
    const type = m.type;
    return type.kind === "primitive" && type.name === "NodeFlags";
}

// ────────────────────────────────────────────────────────────────────────────
// Subtree-facts provider election (plan/02 §3.4 — Go promotion made explicit)
// ────────────────────────────────────────────────────────────────────────────

// Node/base-level hand-written computeSubtreeFacts in ast.go (mirrors Go's
// HAND_WRITTEN_BASES idea, generate-go-ast.ts:222; audited against tsgo
// internal/ast/ast.go).
const HAND_WRITTEN_COMPUTE = new Set([
    "Token", "PrivateIdentifier", "Decorator", "ForInOrOfStatement", "ReturnStatement",
    "CatchClause", "VariableStatement", "VariableDeclaration", "VariableDeclarationList",
    "BindingPattern", "ParameterDeclaration", "BindingElement", "FunctionDeclaration",
    "ClassLikeBase", "HeritageClause", "EnumMember", "EnumDeclaration", "ModuleDeclaration",
    "ImportEqualsDeclaration", "ImportSpecifier", "ImportClause", "ExportAssignment",
    "ExportDeclaration", "ExportSpecifier", "ConstructorDeclaration", "AccessorDeclarationBase",
    "MethodDeclaration", "PropertyDeclaration", "ClassStaticBlockDeclaration",
    "KeywordExpression", "BigIntLiteral", "Identifier", "NoSubstitutionTemplateLiteral",
    "BinaryExpression", "YieldExpression", "ArrowFunction", "FunctionExpression",
    "AsExpression", "SatisfiesExpression", "PropertyAccessExpression", "CallExpression",
    "NewExpression", "MetaProperty", "NonNullExpression", "SpreadElement",
    "TaggedTemplateExpression", "SpreadAssignment", "PropertyAssignment",
    "ShorthandPropertyAssignment", "AwaitExpression", "TypeAssertion",
    "ExpressionWithTypeArguments", "TemplateHead", "TemplateMiddle", "TemplateTail",
    "JsxElement", "JsxAttributes", "JsxNamespacedName", "JsxOpeningElement",
    "JsxSelfClosingElement", "JsxFragment", "JsxOpeningFragment", "JsxClosingFragment",
    "JsxAttribute", "JsxSpreadAttribute", "JsxClosingElement", "JsxExpression", "JsxText",
    "SourceFile",
]);

// Node/base-level hand-written propagateSubtreeFacts in ast.go.
const HAND_WRITTEN_PROPAGATE = new Set([
    "CatchClause", "VariableDeclarationList", "BindingPattern", "ParameterDeclaration",
    "FunctionDeclaration", "ClassDeclaration", "ClassExpression", "ModuleDeclaration",
    "ConstructorDeclaration", "AccessorDeclarationBase", "MethodDeclaration",
    "PropertyDeclaration", "ArrowFunction", "FunctionExpression", "AsExpression",
    "SatisfiesExpression", "PropertyAccessExpression", "ElementAccessExpression",
    "CallExpression", "NewExpression", "ArrayLiteralExpression", "ObjectLiteralExpression",
    "TypeAssertion",
]);

type FactsMethod = "compute" | "propagate" | "worker";

/**
 * Elects the effective provider for a subtree-facts method on a class, by Go's
 * promotion rule: shallowest embedding depth wins; a tie between different
 * providers is a schema-evolution error (Go would fail to compile the same tie).
 */
function effectiveProvider(name: string, method: FactsMethod, extendsKeys: string[], generatesFacts: boolean): string {
    const providers: { id: string; depth: number }[] = [];
    if (method === "compute" && (HAND_WRITTEN_COMPUTE.has(name) || generatesFacts)) {
        providers.push({ id: (generatesFacts ? "gen:" : "hw:") + name, depth: 0 });
    }
    if (method === "propagate" && HAND_WRITTEN_PROPAGATE.has(name)) {
        providers.push({ id: "hw:" + name, depth: 0 });
    }
    const seen = new Map<string, number>();
    const queue: [string, number][] = extendsKeys.map(key => [key, 1]);
    while (queue.length > 0) {
        const [key, depth] = queue.shift()!;
        const prior = seen.get(key);
        if (prior !== undefined && prior <= depth) continue;
        seen.set(key, depth);
        switch (method) {
            case "compute":
                if (key === "CompositeBase") providers.push({ id: "CompositeBase.panic", depth });
                if (key === "TypeSyntaxBase") providers.push({ id: "TypeSyntaxBase", depth });
                if (HAND_WRITTEN_COMPUTE.has(key)) providers.push({ id: "hw:" + key, depth });
                if (key === "NodeDefault") providers.push({ id: "default", depth });
                break;
            case "propagate":
                if (key === "TypeSyntaxBase") providers.push({ id: "TypeSyntaxBase", depth });
                if (HAND_WRITTEN_PROPAGATE.has(key)) providers.push({ id: "hw:" + key, depth });
                if (key === "NodeDefault") providers.push({ id: "default", depth });
                break;
            case "worker":
                if (key === "CompositeBase") providers.push({ id: "CompositeBase.worker", depth });
                if (key === "NodeDefault") providers.push({ id: "default", depth });
                break;
        }
        if (key === "NodeBase") queue.push(["NodeDefault", depth + 1]);
        for (const ext of api.getBase(key)?.extendsKeys ?? []) queue.push([ext, depth + 1]);
    }
    const minDepth = Math.min(...providers.map(p => p.depth));
    const atMin = [...new Set(providers.filter(p => p.depth === minDepth).map(p => p.id))];
    if (atMin.length > 1) {
        throw new Error(`${name}.${method}: provider tie at depth ${minDepth} between ${atMin.join(" & ")} — upstream schema change needs a hand-written tie-breaker (plan/02 §3.4 step 3)`);
    }
    return atMin[0];
}

function effectiveForClass(name: string, method: FactsMethod): string {
    if (name === "Node" || name === "NodeBase") return "default";
    const node = api.getNode(name);
    if (node) return effectiveProvider(name, method, node.extendsKeys, node.generateSubtreeFacts);
    const base = api.getBase(name);
    if (!base) throw new Error(`unknown class ${name}`);
    return effectiveProvider(name, method, base.extendsKeys, false);
}

// ────────────────────────────────────────────────────────────────────────────
// Per-class emission model
// ────────────────────────────────────────────────────────────────────────────

interface ClassModel {
    name: string;
    isNode: boolean;
    node?: NodeType;
    baseClassKey: string; // "NodeBase" ⇒ Node
    /** Interfaces exactly as listed in extends (minus Node-lineage entries), plan/02 §8.3. */
    interfaces: string[];
    /** Mixins/brands first introduced here (BFS order). */
    introduced: string[];
    /** Flattened mixin fields (deduped by name, shallowest-first). */
    flattened: { mixin: string; field: MemberInfo }[];
    hasFacts: boolean;
}

function buildClassModel(name: string, extendsKeys: string[], node?: NodeType): ClassModel {
    const baseClassKey = selectBaseClass(name, extendsKeys);
    const interfaces = extendsKeys.filter(key => !isNodeLineage(key));
    const introduced = newMixins(extendsKeys, baseClassKey);
    const flattened: { mixin: string; field: MemberInfo }[] = [];
    const fieldNames = new Set<string>();
    let hasFacts = false;
    // Fields already provided by the base class chain must not be re-emitted
    // (plan/02 §3.2 step 4, second dedup).
    for (const key of [baseClassKey, ...extendsClosure(baseClassKey)]) {
        for (const field of api.getBase(key)?.fields ?? []) fieldNames.add(field.name);
        if (key === "CompositeBase") fieldNames.add("facts");
    }
    for (const mixin of introduced) {
        if (mixin === "CompositeBase") {
            if (!fieldNames.has("facts")) {
                hasFacts = true;
                fieldNames.add("facts");
            }
            continue;
        }
        for (const field of api.getBase(mixin)!.fields) {
            if (field.noGo || fieldNames.has(field.name)) continue;
            fieldNames.add(field.name);
            flattened.push({ mixin, field });
        }
    }
    return { name, isNode: !!node, node, baseClassKey, interfaces, introduced, flattened, hasFacts };
}

const baseModels: ClassModel[] = nodeLineageBases
    .filter(key => key !== "NodeBase")
    .map(key => buildClassModel(key, api.getBase(key)!.extendsKeys));
const nodeModels: ClassModel[] = api.nodes().map(node => buildClassModel(node.name, node.extendsKeys, node));
const modelByName = new Map<string, ClassModel>([...baseModels, ...nodeModels].map(m => [m.name, m]));

/** Does the class or its C# base chain carry a private `name` field? */
function chainHasPrivateName(model: ClassModel): boolean {
    let current: ClassModel | undefined = model;
    while (current) {
        if (current.flattened.some(f => f.field.name === "name" && f.field.private)) return true;
        if (current.node?.members.some(m => !m.inherited && m.name === "name" && m.private)) return true;
        current = modelByName.get(current.baseClassKey);
    }
    return false;
}

// ────────────────────────────────────────────────────────────────────────────
// Nodes.g.cs
// ────────────────────────────────────────────────────────────────────────────

function emitClassMembers(w: CodeWriter, model: ClassModel): void {
    // Mixin flattening first (Go embedding order), then own schema fields.
    for (const { mixin, field } of model.flattened) {
        const type = csMemberType(field);
        if (isGoPrivate(field)) {
            w.writeLine(`internal ${type} ${field.name}; // ${mixin} (private)`);
        } else {
            const init = type === "string" ? ` = "";` : "";
            const optional = field.optional ? ". Optional" : "";
            if (init !== "") {
                w.writeLine(`public ${type} ${field.name} { get; set; } = ""; // ${mixin}${optional}`);
            } else {
                w.writeLine(`public ${type} ${field.name} { get; set; } // ${mixin}${optional}`);
            }
        }
    }
    if (model.hasFacts) {
        w.writeLine("private uint facts; // CompositeBase (private; atomic via Volatile in CachedSubtreeFacts)");
    }
    const own: MemberInfo[] = model.isNode
        ? model.node!.members.filter(m => !m.inherited && !m.isKindParam() && !m.noGo)
        : (api.getBase(model.name)?.fields ?? []).filter(f => !f.noGo);
    for (const m of own) {
        const type = csMemberType(m);
        const visibility = isGoPrivate(m) ? "internal" : "public";
        const init = type === "string" ? ` = ""` : "";
        const comment = m.optional ? " // Optional" : "";
        w.writeLine(`${visibility} ${type} ${m.name}${init};${comment}`);
    }
}

function generateNodes(): string {
    const w = new CodeWriter();
    for (const line of HEADER) w.writeLine(line);
    w.writeLine();
    w.writeLine("namespace Ts.Ast;");
    w.writeLine();
    w.writeLine("// Brand bases (rule 3, plan/02 §3.3): field-less, pure marker interfaces.");
    w.writeLine("// TypeSyntaxBase behavior re-anchoring lives in Accessors.g.cs (plan/02 §3.4).");
    w.writeLine();
    for (const key of brandBases) {
        const parents = api.getBase(key)!.extendsKeys;
        w.writeLine(`public interface ${key}${parents.length > 0 ? " : " + parents.join(", ") : ""}`);
        w.writeLine("{");
        w.writeLine("}");
        w.writeLine();
    }
    w.writeLine("// Data mixins (rule 2, plan/02 §3.2): interface + fields flattened into carriers.");
    w.writeLine("// Private Go fields (modifiers/name/facts/text) stay out of the interfaces and are");
    w.writeLine("// reached through the Node virtual accessors (plan/02 §8.1).");
    w.writeLine();
    for (const key of mixinBases) {
        const base = api.getBase(key)!;
        const parents = base.extendsKeys;
        const publicFields = base.fields.filter(f => !f.noGo && !isGoPrivate(f));
        w.writeLine(`public interface ${key}${parents.length > 0 ? " : " + parents.join(", ") : ""}`);
        w.writeLine("{");
        w.increaseIndent();
        for (const f of publicFields) {
            w.writeLine(`${csMemberType(f)} ${f.name} { get; set; }${f.optional ? " // Optional" : ""}`);
        }
        w.decreaseIndent();
        w.writeLine("}");
        w.writeLine();
    }
    w.writeLine("// Node-lineage abstract bases (rule 1, plan/02 §3.1). NodeBase itself is the");
    w.writeLine("// hand-written Ts.Ast.Node (Go Node + NodeDefault + NodeBase collapsed, plan/02 §1.2).");
    w.writeLine();
    for (const model of baseModels) {
        const parents = [csBaseClassName(model.baseClassKey), ...model.interfaces];
        w.block(`public abstract partial class ${model.name} : ${parents.join(", ")}`, () => {
            emitClassMembers(w, model);
        });
        w.writeLine();
    }
    w.writeLine("// Concrete node classes. Only this primary declaration carries the base/interface");
    w.writeLine("// list (plan/04 §2.2); overrides live in Visitors.g.cs/Accessors.g.cs.");
    w.writeLine();
    for (const model of nodeModels) {
        if (model.node!.handWritten) {
            w.writeLine(`// ${model.name}: class and factory methods hand-written in Ast/SourceFile.cs (ast.json handWritten).`);
            w.writeLine();
            continue;
        }
        const parents = [csBaseClassName(model.baseClassKey), ...model.interfaces];
        w.block(`public sealed partial class ${model.name} : ${parents.join(", ")}`, () => {
            emitClassMembers(w, model);
        });
        w.writeLine();
    }
    return w.toString();
}

// ────────────────────────────────────────────────────────────────────────────
// Accessors.g.cs (mixin accessor overrides, Name(), workers, TypeSyntaxBase)
// ────────────────────────────────────────────────────────────────────────────

/** Node virtual accessor introduced by each mixin (plan/02 §8.2). */
const MIXIN_ACCESSORS: Record<string, string> = {
    FlowNodeBase: "FlowNodeData",
    DeclarationBase: "DeclarationData",
    ExportableBase: "ExportableData",
    LocalsContainerBase: "LocalsContainerData",
    FunctionLikeBase: "FunctionLikeData",
    ClassLikeBase: "ClassLikeData",
    BodyBase: "BodyData",
    LiteralLikeNodeBase: "LiteralLikeData",
    TemplateLiteralLikeNodeBase: "TemplateLiteralLikeData",
};

function generateAccessors(): { text: string; nameAccessorCount: number } {
    const w = new CodeWriter();
    for (const line of HEADER) w.writeLine(line);
    w.writeLine();
    w.writeLine("using System;");
    w.writeLine();
    w.writeLine("namespace Ts.Ast;");
    w.writeLine();
    w.writeLine("// Mixin virtual-accessor overrides at their introduction classes (plan/02 §3.2");
    w.writeLine("// step 5 / §8.2), generated Name() accessors (generate-go-ast.ts:747-765),");
    w.writeLine("// CompositeBase cached workers and TypeSyntaxBase re-anchoring (plan/02 §3.4).");
    w.writeLine();
    let nameAccessorCount = 0;
    for (const model of [...baseModels, ...nodeModels]) {
        if (model.node?.handWritten) continue; // SourceFile: hand-written in Ast/SourceFile.cs
        const lines: string[] = [];
        for (const mixin of model.introduced) {
            const accessor = MIXIN_ACCESSORS[mixin];
            if (accessor) {
                lines.push(`public override ${mixin}? ${accessor}() => this;`);
            }
            if (mixin === "ModifiersBase") {
                lines.push("public override ModifierList? Modifiers() => modifiers;");
                lines.push("internal override void SetModifiers(ModifierList? modifiers) { this.modifiers = modifiers; }");
            }
        }
        if (model.isNode) {
            const nameMember = schemaMembers(model.node!).find(m => m.name === "name");
            const isPrivate = nameMember && (nameMember.inherited ? (nameMember.inheritedField?.private ?? false) : nameMember.private);
            if (nameMember && isPrivate) {
                lines.push("public override DeclarationName? Name() => name;");
                nameAccessorCount++;
            }
        }
        // Subtree-facts election (plan/02 §3.4): emit only where the effective Go
        // provider differs from what the C# base-class chain already supplies.
        const parentName = csBaseClassName(model.baseClassKey);
        if (model.hasFacts) {
            if (effectiveForClass(model.name, "worker") !== "CompositeBase.worker") {
                throw new Error(`${model.name}: introduces CompositeBase but its effective worker is not the cached one`);
            }
            lines.push("internal override SubtreeFacts SubtreeFactsWorker() => CachedSubtreeFacts(ref facts); // CompositeBase (ast.go:1599-1607)");
        }
        for (const method of ["compute", "propagate"] as const) {
            const eff = effectiveForClass(model.name, method);
            const parentEff = effectiveForClass(parentName, method);
            if (eff === parentEff) continue;
            if (eff.startsWith("hw:") || eff.startsWith("gen:")) continue; // hand-written partial (phase 3) or Visitors.g.cs
            if (eff === "TypeSyntaxBase") {
                lines.push(method === "compute"
                    ? "internal override SubtreeFacts ComputeSubtreeFacts() => Ts.Ast.SubtreeFacts.SubtreeContainsTypeScript; // TypeSyntaxBase (ast.go:1616)"
                    : "internal override SubtreeFacts PropagateSubtreeFacts() => Ts.Ast.SubtreeFacts.SubtreeContainsTypeScript; // TypeSyntaxBase (ast.go:1618)");
            } else if (eff === "CompositeBase.panic") {
                lines.push(`internal override SubtreeFacts ComputeSubtreeFacts() => throw new InvalidOperationException("not implemented"); // CompositeBase (ast.go:1609-1612)`);
            } else {
                throw new Error(`${model.name}.${method}: unexpected effective provider ${eff} (base provides ${parentEff})`);
            }
        }
        if (lines.length === 0) continue;
        const kindKeyword = model.isNode ? "sealed" : "abstract";
        w.block(`public ${kindKeyword} partial class ${model.name}`, () => {
            for (const line of lines) w.writeLine(line);
        });
        w.writeLine();
    }
    return { text: w.toString(), nameAccessorCount };
}

// ────────────────────────────────────────────────────────────────────────────
// NodeFactory.g.cs
// ────────────────────────────────────────────────────────────────────────────

function factoryParams(members: MemberInfo[]): string {
    return members.map(m => `${csMemberType(m)} ${csIdentifier(m.goParamName())}`).join(", ");
}

function emitNewFactory(
    w: CodeWriter,
    funcName: string,
    kindName: string,
    node: NodeType,
    members: MemberInfo[],
    kindMember: MemberInfo | undefined,
    nodeFlagsMembers: MemberInfo[],
): void {
    w.block(`public Node ${funcName}(${factoryParams(members)})`, () => {
        w.writeLine(`var data = new ${node.name}();`);
        for (const m of members) {
            if (m.isKindParam()) continue;
            if (isNodeFlagsMember(m)) continue;
            const param = csIdentifier(m.goParamName());
            const value = m.bitmask ? `${param} & ${mapGoConstant(m.bitmask)}` : param;
            w.writeLine(`data.${m.name} = ${value};`);
        }
        if (hasTextContent(node)) {
            w.writeLine("textCount++;");
        }
        const kindArg = kindMember ? csIdentifier(kindMember.goParamName()) : `SyntaxKind.${kindName}`;
        if (nodeFlagsMembers.length > 0) {
            w.writeLine(`var node = NewNode(${kindArg}, data);`);
            for (const m of nodeFlagsMembers) {
                const param = csIdentifier(m.goParamName());
                if (m.bitmask) {
                    w.writeLine(`node.Flags |= ${param} & ${mapGoConstant(m.bitmask)};`);
                } else {
                    w.writeLine(`node.Flags = ${param};`);
                }
            }
            w.writeLine("return node;");
        } else {
            w.writeLine(`return NewNode(${kindArg}, data);`);
        }
    });
    w.writeLine();
}

function generateNewFactory(w: CodeWriter, node: NodeType): number {
    const members = schemaMembers(node);
    const kindMember = members.find(m => m.isKindParam());
    const nodeFlagsMembers = members.filter(isNodeFlagsMember);
    emitNewFactory(w, `New${node.name}`, node.syntaxKindName, node, members, kindMember, nodeFlagsMembers);
    for (const alias of node.kindAliases) {
        emitNewFactory(w, `New${alias}`, alias, node, members, kindMember, nodeFlagsMembers);
    }
    return 1 + node.kindAliases.length;
}

function generateUpdateFactory(w: CodeWriter, node: NodeType): boolean {
    const members = schemaMembers(node);
    const updateMembers = members.filter(m => !m.isKindParam());
    if (updateMembers.length === 0) return false;
    // Leaf nodes (no child AST node members) don't get Update methods.
    if (!updateMembers.some(m => m.isChild())) return false;

    const params = [`${node.name} node`, ...updateMembers.map(m => `${csMemberType(m)} ${csIdentifier(m.goParamName())}`)].join(", ");
    w.block(`public Node Update${node.name}(${params})`, () => {
        const comparisons = updateMembers.map(m => {
            const param = csIdentifier(m.goParamName());
            const type = m.type;
            if (type.kind === "list" && type.listKind === "raw") {
                return `!ReferenceEquals(${param}, node.${m.name})`; // Go: !core.Same (slice identity)
            }
            return `${param} != node.${m.name}`;
        });
        const newArgs = members.map(m => (m.isKindParam() ? "node.Kind" : csIdentifier(m.goParamName()))).join(", ");
        w.block(`if (${comparisons.join(" || ")})`, () => {
            if (node.kindAliases.length > 0) {
                w.writeLine("switch (node.Kind)");
                w.writeLine("{");
                w.increaseIndent();
                w.writeLine(`case SyntaxKind.${node.syntaxKindName}:`);
                w.increaseIndent();
                w.writeLine(`return UpdateNode(New${node.name}(${newArgs}), node.AsNode(), hooks);`);
                w.decreaseIndent();
                for (const alias of node.kindAliases) {
                    w.writeLine(`case SyntaxKind.${alias}:`);
                    w.increaseIndent();
                    w.writeLine(`return UpdateNode(New${alias}(${newArgs}), node.AsNode(), hooks);`);
                    w.decreaseIndent();
                }
                w.writeLine("default:");
                w.increaseIndent();
                w.writeLine(`throw new InvalidOperationException("unexpected kind in Update${node.name}: " + node.Kind.ToDisplayString());`);
                w.decreaseIndent();
                w.decreaseIndent();
                w.writeLine("}");
            } else {
                w.writeLine(`return UpdateNode(New${node.name}(${newArgs}), node.AsNode(), hooks);`);
            }
        });
        w.writeLine("return node.AsNode();");
    });
    w.writeLine();
    return true;
}

function generateFactory(): { text: string; newCount: number; updateCount: number } {
    const w = new CodeWriter();
    for (const line of HEADER) w.writeLine(line);
    w.writeLine();
    w.writeLine("using System;");
    w.writeLine();
    w.writeLine("namespace Ts.Ast;");
    w.writeLine();
    w.writeLine("// NodeFactory generated surface (plan/04 §2.2 #2): the ~50 Go arena fields are");
    w.writeLine("// deliberately absent (GC replaces arenas); hooks/nodeCount/textCount remain.");
    w.writeLine("// Construction helpers (NewNode/InitNode/UpdateNode/CloneNode) are hand-written");
    w.writeLine("// in Ast/NodeFactory.cs (ast.go:60-119).");
    let newCount = 0;
    let updateCount = 0;
    w.block("public sealed partial class NodeFactory", () => {
        w.writeLine("internal NodeFactoryHooks hooks;");
        w.writeLine("internal int nodeCount;");
        w.writeLine("internal int textCount;");
        w.writeLine();
        for (const node of api.nodes()) {
            if (node.handWritten) continue;
            newCount += generateNewFactory(w, node);
            if (generateUpdateFactory(w, node)) updateCount++;
        }
    });
    return { text: w.toString(), newCount, updateCount };
}

// ────────────────────────────────────────────────────────────────────────────
// Visitors.g.cs (ForEachChild / VisitEachChild / Clone / computeSubtreeFacts)
// ────────────────────────────────────────────────────────────────────────────

function forEachChildLines(node: NodeType): string[] | undefined {
    const childMembers = schemaMembers(node).filter(m => m.isChild());
    if (childMembers.length === 0) return undefined;
    // Nodes with runtime-dependent child ordering delegate to a hand-written function.
    if (node.handWrittenVisitor) {
        return [`return ForEachChild_${node.name}(this, v);`];
    }
    const parts = childMembers.map(m => {
        const listKind = m.listKind;
        if (listKind === "raw") return `VisitNodes(v, ${m.name})`;
        if (listKind === "ModifierList") return `VisitModifiers(v, ${m.name})`;
        if (listKind === "NodeList") return `VisitNodeList(v, ${m.name})`;
        return `Visit(v, ${m.name})`;
    });
    if (parts.length <= 3) {
        return [`return ${parts.join(" || ")};`];
    }
    const lines = [`return ${parts[0]} ||`];
    for (let i = 1; i < parts.length - 1; i++) lines.push(`    ${parts[i]} ||`);
    lines.push(`    ${parts[parts.length - 1]};`);
    return lines;
}

function visitEachChildLines(node: NodeType): string[] | undefined {
    const members = schemaMembers(node);
    const childMembers = members.filter(m => m.isChild());
    if (childMembers.length === 0) return undefined;
    if (node.handWrittenVisitor) {
        return [`return VisitEachChild_${node.name}(this, v);`];
    }
    const lines: string[] = [];
    const updateMembers = members.filter(m => !m.isKindParam());
    const rawListLocals = new Map<string, string>();
    for (const m of updateMembers) {
        const type = m.type;
        if (m.isChild() && type.kind === "list" && type.listKind === "raw") {
            const localName = csIdentifier(m.goParamName());
            rawListLocals.set(m.name, localName);
            // Go: core.SameMap(node.X, func(n *Node) *Node { return v.visitNode(n) })
            lines.push(`var ${localName} = CoreUtil.SameMap(${m.name}, n => v.visitNode(n)!);`);
        }
    }
    const args = updateMembers.map(m => {
        if (!m.isChild()) return m.name;
        if (rawListLocals.has(m.name)) return rawListLocals.get(m.name)!;
        const type = m.type;
        const listKind = m.listKind;
        if (m.visit) return `v.visit${api.capitalize(m.visit)}(${m.name})`;
        if (listKind === "ModifierList") return `v.visitModifiers(${m.name})`;
        if (listKind === "NodeList") return `v.visitNodes(${m.name})`;
        if (type.kind === "primitive" && type.name === "Token") return `v.visitToken(${m.name})`;
        return `v.visitNode(${m.name})`;
    }).join(", ");
    lines.push(`return v.Factory.Update${node.name}(this, ${args});`);
    return lines;
}

function cloneLines(node: NodeType): string[] {
    const members = schemaMembers(node);
    // Clone reads fields directly (it is a member of the class, so private fields are
    // reachable); the inherited ModifierLike member goes through Modifiers(), as in Go.
    const args = members.map(m => {
        if (m.isKindParam()) return "Kind";
        const type = m.declaredType;
        if (m.inherited && type.kind === "alias" && type.name === "ModifierLike") {
            return "Modifiers()";
        }
        return m.name;
    }).join(", ");
    if (node.kindAliases.length === 0) {
        return [`return NodeFactory.CloneNode(f.AsNodeFactory().New${node.name}(${args}), AsNode(), f.AsNodeFactory().hooks);`];
    }
    const lines: string[] = ["switch (Kind)", "{"];
    lines.push(`    case SyntaxKind.${node.syntaxKindName}:`);
    lines.push(`        return NodeFactory.CloneNode(f.AsNodeFactory().New${node.name}(${args}), AsNode(), f.AsNodeFactory().hooks);`);
    for (const alias of node.kindAliases) {
        lines.push(`    case SyntaxKind.${alias}:`);
        lines.push(`        return NodeFactory.CloneNode(f.AsNodeFactory().New${alias}(${args}), AsNode(), f.AsNodeFactory().hooks);`);
    }
    lines.push("    default:");
    lines.push(`        throw new InvalidOperationException("unexpected kind in ${node.name}.Clone: " + Kind.ToDisplayString());`);
    lines.push("}");
    return lines;
}

function subtreeFactsTerm(m: MemberInfo): string {
    if (m.listKind === "ModifierList") return `PropagateModifierListSubtreeFacts(${m.name})`;
    if (m.type.kind === "list") return `PropagateNodeListSubtreeFacts(${m.name}, PropagateSubtreeFacts)`;
    return `PropagateSubtreeFacts(${m.name})`;
}

function computeSubtreeFactsLines(node: NodeType): string[] | undefined {
    if (!node.generateSubtreeFacts) return undefined;
    const childMembers = schemaMembers(node).filter(m => m.isChild());
    if (childMembers.length === 0) return ["return Ts.Ast.SubtreeFacts.None;"];
    const lines: string[] = [];
    for (let i = 0; i < childMembers.length; i++) {
        const term = subtreeFactsTerm(childMembers[i]);
        const prefix = i === 0 ? "return " : "    ";
        const suffix = i < childMembers.length - 1 ? " |" : ";";
        lines.push(`${prefix}${term}${suffix}`);
    }
    return lines;
}

function generateVisitors(): { text: string; forEachChildCount: number; visitEachChildCount: number; cloneCount: number; computeCount: number } {
    const w = new CodeWriter();
    for (const line of HEADER) w.writeLine(line);
    w.writeLine();
    w.writeLine("using System;");
    w.writeLine("using Ts.Core;");
    w.writeLine();
    w.writeLine("namespace Ts.Ast;");
    w.writeLine();
    w.writeLine("// Per-node ForEachChild/VisitEachChild/Clone overrides and the generated");
    w.writeLine("// computeSubtreeFacts bodies. The Go-side Kind-switch ForEachChild dispatch");
    w.writeLine("// (generate-go-ast.ts:506-527) is deliberately absent: it exists to appease Go");
    w.writeLine("// escape analysis; C# virtual dispatch is the equivalent form (plan/02 §4.2).");
    w.writeLine();
    let forEachChildCount = 0;
    let visitEachChildCount = 0;
    let cloneCount = 0;
    let computeCount = 0;
    for (const node of api.nodes()) {
        if (node.handWritten) continue;
        const fec = forEachChildLines(node);
        const vec = visitEachChildLines(node);
        const clone = cloneLines(node);
        const compute = computeSubtreeFactsLines(node);
        w.block(`public sealed partial class ${node.name}`, () => {
            let first = true;
            const method = (header: string, body: string[]) => {
                if (!first) w.writeLine();
                first = false;
                w.block(header, () => {
                    for (const line of body) w.writeLine(line);
                });
            };
            if (fec) {
                method("public override bool ForEachChild(Visitor v)", fec);
                forEachChildCount++;
            }
            if (vec) {
                method("public override Node VisitEachChild(NodeVisitor v)", vec);
                visitEachChildCount++;
            }
            method("public override Node Clone(NodeFactoryCoercible f)", clone);
            cloneCount++;
            if (compute) {
                method("internal override SubtreeFacts ComputeSubtreeFacts()", compute);
                computeCount++;
            }
        });
        w.writeLine();
    }
    return { text: w.toString(), forEachChildCount, visitEachChildCount, cloneCount, computeCount };
}

// ────────────────────────────────────────────────────────────────────────────
// NodeCasts.g.cs (As* casts, Is* guards, kind alias guards)
// ────────────────────────────────────────────────────────────────────────────

function generateIsFunction(w: CodeWriter, node: NodeType): number {
    let count = 0;
    const kindTypes = node.kindTypes();
    if (node.kindType.kind === "typeParameter") {
        w.block(`public static bool Is${node.name}(Node node)`, () => {
            w.writeLine("switch (node.Kind)");
            w.writeLine("{");
            w.increaseIndent();
            for (const kind of kindTypes) w.writeLine(`case SyntaxKind.${kind.name}:`);
            w.increaseIndent();
            w.writeLine("return true;");
            w.decreaseIndent();
            w.decreaseIndent();
            w.writeLine("}");
            w.writeLine("return false;");
        });
        w.writeLine();
        return 1;
    }
    if (node.isMultiKind()) {
        for (const kind of kindTypes) {
            w.block(`public static bool Is${kind.name}(Node node)`, () => {
                w.writeLine(`return node.Kind == SyntaxKind.${kind.name};`);
            });
            w.writeLine();
            count++;
        }
        return count;
    }
    w.block(`public static bool Is${node.name}(Node node)`, () => {
        w.writeLine(`return node.Kind == SyntaxKind.${node.syntaxKindName};`);
    });
    w.writeLine();
    count++;
    for (const alias of node.kindAliases) {
        w.block(`public static bool Is${alias}(Node node)`, () => {
            w.writeLine(`return node.Kind == SyntaxKind.${alias};`);
        });
        w.writeLine();
        count++;
    }
    return count;
}

/** Go guard name: "IsTokenKind" etc. — capital I, "Syntax" dropped. */
function goKindGuardName(aliasName: string): string {
    const tsName = kindGuardName(aliasName);
    return tsName.charAt(0).toUpperCase() + tsName.slice(1);
}

function generateCasts(): { text: string; asCount: number; isCount: number; guardCount: number } {
    const w = new CodeWriter();
    for (const line of HEADER) w.writeLine(line);
    w.writeLine();
    w.writeLine("namespace Ts.Ast;");
    w.writeLine();
    let asCount = 0;
    w.writeLine("// As*() casts (plan/02 §4.3): Go `n.data.(*X)` panics on mismatch; the C# cast");
    w.writeLine("// throws InvalidCastException — the same contract.");
    w.block("public abstract partial class Node", () => {
        for (const node of api.nodes()) {
            w.writeLine(`public ${node.name} As${node.name}() => (${node.name})this;`);
            asCount++;
        }
    });
    w.writeLine();
    w.writeLine("// Is*() type guards and kind alias guards. Host class per review verdict R7:");
    w.writeLine("// Ts.Ast.NodeTests (mirrors TypeScript's factory/nodeTests.ts domain).");
    let isCount = 0;
    let guardCount = 0;
    w.block("public static class NodeTests", () => {
        for (const node of api.nodes()) {
            isCount += generateIsFunction(w, node);
        }
        // JSDocSyntaxKind → IsJSDocKind conflicts with the hand-written IsJSDocKind in
        // utilities.go (JSDoc NODE kinds — a different semantic); skip, as Go does
        // (generate-go-ast.ts:709).
        const skipGuards = new Set(["IsJSDocKind"]);
        for (const guard of api.kindGuards()) {
            const funcName = goKindGuardName(guard.aliasName);
            if (skipGuards.has(funcName)) continue;
            if (guard.type === "range") {
                w.block(`public static bool ${funcName}(SyntaxKind kind)`, () => {
                    w.writeLine(`return kind >= SyntaxKind.${guard.first} && kind <= SyntaxKind.${guard.last};`);
                });
                w.writeLine();
            } else {
                const expanded = api.expandKindAliasMembers(guard.aliasName);
                w.block(`public static bool ${funcName}(SyntaxKind kind)`, () => {
                    w.writeLine("switch (kind)");
                    w.writeLine("{");
                    w.increaseIndent();
                    for (const member of expanded) w.writeLine(`case SyntaxKind.${member.name}:`);
                    w.increaseIndent();
                    w.writeLine("return true;");
                    w.decreaseIndent();
                    w.decreaseIndent();
                    w.writeLine("}");
                    w.writeLine("return false;");
                });
                w.writeLine();
            }
            guardCount++;
        }
    });
    return { text: w.toString(), asCount, isCount, guardCount };
}

// ────────────────────────────────────────────────────────────────────────────
// SyntaxKind.g.cs (mirror of generateKind, generate-go-ast.ts:904-1006)
// ────────────────────────────────────────────────────────────────────────────

function generateSyntaxKind(): { text: string; elementCount: number } {
    const elements = api.kindElements();
    const markers = api.kindMarkers();
    const kindUnions = api.kindAliases();

    // Marker/union reference validation preserved verbatim (generate-go-ast.ts:923-945).
    const definedKinds = new Set<string>();
    for (const element of elements) {
        if (element.name) definedKinds.add(element.name);
    }
    const markerNames = new Set(markers.map(m => m.name));
    for (const marker of markers) {
        if (!definedKinds.has(marker.value) && !markerNames.has(marker.value)) {
            throw new Error(`Kind marker ${marker.name} references undefined kind or marker "${marker.value}"`);
        }
    }
    for (const kindUnion of kindUnions) {
        for (const m of kindUnion.members) {
            if (!definedKinds.has(m) && !api.hasKindAlias(m)) {
                throw new Error(`Kind union ${kindUnion.name} references undefined kind or union "${m}"`);
            }
        }
    }

    const w = new CodeWriter();
    for (const line of HEADER) w.writeLine(line);
    w.writeLine();
    w.writeLine("namespace Ts.Ast;");
    w.writeLine();
    w.writeLine("// Go `type Kind int16` (kind_generated.go). The type is renamed SyntaxKind (the");
    w.writeLine("// single sanctioned type rename, plan/05 §1.1); members drop the Go `Kind` prefix.");
    w.writeLine("// Marker members (FirstAssignment etc.) reuse element values, as in Go.");
    w.block("public enum SyntaxKind : short", () => {
        for (const el of elements) {
            if (!el.name) {
                w.writeLine(`// ${el.comment}`);
                continue;
            }
            w.writeLine(`${el.name},${el.comment ? ` // ${el.comment}` : ""}`);
        }
        w.writeLine("Count,");
        for (const marker of markers) {
            w.writeLine(`${marker.name} = ${marker.value},`);
        }
    });
    return { text: w.toString(), elementCount: definedKinds.size };
}

// ────────────────────────────────────────────────────────────────────────────
// GlobalUsings.g.cs (plan/02 §13: the alias families)
// ────────────────────────────────────────────────────────────────────────────

function generateGlobalUsings(): { text: string; aliasCount: number } {
    const w = new CodeWriter();
    for (const line of HEADER) w.writeLine(line);
    w.writeLine();
    w.writeLine("// Go type aliases → C# global usings (plan/02 §13). Aliases are per-compilation:");
    w.writeLine("// consuming projects link this file via <Compile Include=… Link=…>.");
    w.writeLine();
    let aliasCount = 0;
    w.writeLine("// Node type aliases (one per concrete node) and instantiation aliases.");
    for (const node of api.nodes()) {
        w.writeLine(`global using ${node.name}Node = Ts.Ast.Node;`);
        aliasCount++;
    }
    for (const node of api.nodes()) {
        for (const alias of node.instantiationAliases) {
            w.writeLine(`global using ${alias.name} = Ts.Ast.Node; // ${node.name}<${alias.typeArg}>`);
            aliasCount++;
        }
    }
    w.writeLine();
    w.writeLine("// NodeList aliases.");
    for (const listAlias of api.listAliases()) {
        w.writeLine(`global using ${listAlias.name} = Ts.Ast.NodeList; // NodeList[*${listAlias.elementTypeName}]`);
        aliasCount++;
    }
    w.writeLine();
    w.writeLine("// Node union aliases.");
    for (const alias of api.nodeAliases()) {
        let comment = "";
        if (alias.isBaseAlias && alias.baseKey) comment = ` // Node with ${alias.baseKey}`;
        else if (alias.isUnion) comment = ` // ${alias.unionMemberNames.join(" | ")}`;
        w.writeLine(`global using ${alias.name} = Ts.Ast.Node;${comment}`);
        aliasCount++;
    }
    w.writeLine();
    w.writeLine("// Kind union aliases (kind_generated.go tail).");
    for (const { name, members } of api.kindAliases()) {
        const expand = (ms: string[]): string[] => {
            const result: string[] = [];
            for (const m of ms) {
                const alias = api.getKindAlias(m);
                if (alias) result.push(...expand(alias.members));
                else result.push(m);
            }
            return result;
        };
        w.writeLine(`global using ${name} = Ts.Ast.SyntaxKind; // ${expand(members).join(" | ")}`);
        aliasCount++;
    }
    return { text: w.toString(), aliasCount };
}

// ────────────────────────────────────────────────────────────────────────────
// Main
// ────────────────────────────────────────────────────────────────────────────

function assertCounts(): void {
    const nodeCount = api.nodes().length;
    const baseCount = api.bases().length;
    const kindCount = api.kindElements().filter(e => e.name).length;
    const expectNodes = expectedCount("astNodes");
    const expectBases = expectedCount("astBases");
    const expectKinds = expectedCount("astKindElements");
    if (nodeCount !== expectNodes || baseCount !== expectBases || kindCount !== expectKinds) {
        throw new Error(
            `ast.json counts drifted: nodes=${nodeCount} (expected ${expectNodes}), bases=${baseCount} (expected ${expectBases}), ` +
            `kind elements=${kindCount} (expected ${expectKinds}). Upstream bumps must update expected-counts.json first (plan/04 §2.5).`,
        );
    }
}

function assertNameAccessorReachability(): void {
    // Every concrete carrier of a private `name` (via NamedMemberBase/ClassLikeBase or a
    // direct private member) must get a generated Name() on itself or an ancestor —
    // C# has no Go promotion fallback.
    for (const model of nodeModels) {
        if (model.node!.handWritten) continue;
        if (!chainHasPrivateName(model)) continue;
        let covered = false;
        let current: ClassModel | undefined = model;
        while (current && !covered) {
            if (current.isNode) {
                const nameMember = schemaMembers(current.node!).find(m => m.name === "name");
                const isPrivate = nameMember && (nameMember.inherited ? (nameMember.inheritedField?.private ?? false) : nameMember.private);
                covered = !!(nameMember && isPrivate);
            }
            current = modelByName.get(current.baseClassKey);
        }
        if (!covered) {
            throw new Error(`${model.name}: carries a private name field but no Name() accessor is generated on it or an ancestor`);
        }
    }
}

function main(): void {
    console.log("Generating C# AST code...");
    assertCounts();
    assertNameAccessorReachability();

    const nodes = generateNodes();
    const casts = generateCasts();
    const factory = generateFactory();
    const visitors = generateVisitors();
    const accessors = generateAccessors();
    const kind = generateSyntaxKind();
    const usings = generateGlobalUsings();

    writeIfChanged(path.join(OUT_DIR, "Nodes.g.cs"), nodes);
    writeIfChanged(path.join(OUT_DIR, "NodeCasts.g.cs"), casts.text);
    writeIfChanged(path.join(OUT_DIR, "NodeFactory.g.cs"), factory.text);
    writeIfChanged(path.join(OUT_DIR, "Visitors.g.cs"), visitors.text);
    writeIfChanged(path.join(OUT_DIR, "Accessors.g.cs"), accessors.text);
    writeIfChanged(path.join(OUT_DIR, "SyntaxKind.g.cs"), kind.text);
    writeIfChanged(path.join(OUT_DIR, "GlobalUsings.g.cs"), usings.text);

    console.log(
        `gen:ast counts: nodes=${api.nodes().length} bases=${api.bases().length} kinds=${kind.elementCount} ` +
        `As*=${casts.asCount} Is*=${casts.isCount} kindGuards=${casts.guardCount} New*=${factory.newCount} Update*=${factory.updateCount} ` +
        `ForEachChild=${visitors.forEachChildCount} VisitEachChild=${visitors.visitEachChildCount} Clone=${visitors.cloneCount} ` +
        `computeSubtreeFacts=${visitors.computeCount} Name()=${accessors.nameAccessorCount} aliases=${usings.aliasCount}`,
    );
}

main();
